/** The iOS client's spec: api/openapi.yaml with every enum under components/schemas opened into the
 * generator's documented open form, `anyOf: [known, { type: string }]`, so an app already installed
 * decodes a value the API adds later (a sixth platform, a new roster slot, a new device scope) as an
 * unknown string instead of failing the whole answer (Lane 173 review, H2). A named enum's known
 * values move to `<Name>Known`. Request parameters stay closed: what the app sends, it knows. The API's
 * own spec, its Go and its TypeScript are untouched; this file is generated, committed, and checked
 * by `make -C api check-gen` (shared/scripts/check-gen.ts).
 *
 *   node apps/ios/scripts/gen-openapi.ts */
import { readFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { join } from 'node:path';
import { REPOSITORY, writeOutputs, type Outputs } from '../../../shared/scripts/generated.ts';

const SOURCE = 'api/openapi.yaml';
export const OUTPUT = 'apps/ios/Packages/CommishAPI/Sources/CommishAPI/openapi.yaml';
const SCHEMAS = '#/components/schemas/';
const KNOWN = 'Known';

type Node = Record<string, unknown>;

const isObject = (value: unknown): value is Node =>
	typeof value === 'object' && value !== null && !Array.isArray(value);

function isStringEnum(node: Node): boolean {
	return (
		Array.isArray(node.enum) &&
		(node.type === undefined || node.type === 'string') &&
		node.enum.every((v) => typeof v === 'string')
	);
}

/** The enum's own keys (type, enum) and the keys that describe the slot it fills (the rest). */
function split(node: Node): { closed: Node; outer: Node } {
	const { type = 'string', enum: values, ...outer } = node;
	return { closed: { type, enum: values }, outer };
}

function openInline(node: Node): Node {
	const { closed, outer } = split(node);
	return { ...outer, anyOf: [closed, { type: 'string' }] };
}

/** A schema with every enum inside it opened, a new object: properties, array items, the members of
 * allOf, anyOf and oneOf, and additionalProperties. */
function walk(node: unknown): unknown {
	if (Array.isArray(node)) return node.map(walk);
	if (!isObject(node)) return node;
	if (isStringEnum(node)) return openInline(node);
	return Object.fromEntries(Object.entries(node).map(([key, value]) => [key, walk(value)]));
}

/** The document with its schemas' enums opened; the input is not changed. */
export function openEnums(doc: Node): Node {
	const components = isObject(doc.components) ? doc.components : {};
	const schemas = isObject(components.schemas) ? components.schemas : {};
	const opened: Node = {};
	for (const [name, schema] of Object.entries(schemas)) {
		if (isObject(schema) && isStringEnum(schema)) {
			const { closed, outer } = split(schema);
			opened[`${name}${KNOWN}`] = closed;
			opened[name] = {
				...outer,
				anyOf: [{ $ref: `${SCHEMAS}${name}${KNOWN}` }, { type: 'string' }]
			};
		} else {
			opened[name] = walk(schema);
		}
	}
	return { ...doc, components: { ...components, schemas: opened } };
}

/** The web's YAML library (web/package.json devDependencies). */
function yaml(): {
	parse: (text: string) => unknown;
	stringify: (value: unknown, options: object) => string;
} {
	const web = createRequire(join(REPOSITORY, 'web/package.json'));
	return web('yaml') as ReturnType<typeof yaml>;
}

export async function generate(): Promise<Outputs> {
	const { parse, stringify } = yaml();
	const doc = parse(await readFile(join(REPOSITORY, SOURCE), 'utf8')) as Node;
	const header =
		`# Generated by apps/ios/scripts/gen-openapi.ts from ${SOURCE}, every schema enum opened. ` +
		'Do not edit: edit the source and run `npm run gen:shared` in web/.\n';
	const text = stringify(openEnums(doc), { lineWidth: 0, aliasDuplicateObjects: false });
	return new Map([[OUTPUT, header + text]]);
}

if (import.meta.main) await writeOutputs(await generate());
